(async () => {
  await GameStudio.ready();
  const { questions } = await GameStudio.getData();
  let i = 0, score = 0;
  const $ = id => document.getElementById(id);
  function show() {
    if (i >= questions.length) return end();
    const q = questions[i];
    $('progress').textContent = 'Question ' + (i + 1) + ' of ' + questions.length;
    $('question').textContent = q.q;
    $('options').innerHTML = '';
    q.options.forEach((text, k) => {
      const b = document.createElement('button');
      b.textContent = text;
      b.onclick = () => { if (k === q.answer) score += 10; i++; show(); };
      $('options').appendChild(b);
    });
  }
  async function end() {
    $('question').textContent = 'Done: ' + score + ' points';
    $('options').innerHTML = '';
    await GameStudio.submitScore(score, { answered: questions.length });
    await GameStudio.finish();
  }
  show();
})();
